// Tests for BmpDecoderGpu (Images/Bmp).
//
// Fixtures (TestData/Bmp, generated by scripts/images/make_bmp_fixtures.py) cover 1/4/8 bit palettes (short
// palettes, top-down, BITMAPCOREHEADER), 16 bit (RGB555, RGB565, 4-4-4-4, 1-5-5-5), 24 bit, 32 bit BI_RGB with
// and without alpha, BITFIELDS / ALPHABITFIELDS with the V2..V5 headers and arbitrary masks, RLE4 and RLE8
// (absolute runs, deltas, uncovered pixels). The expected pixels (.rgba8) are derived from the sample arrays the
// files were BUILT from, by the conventions documented in BmpDecoderGpu - not from any decoder; Pillow
// cross-checks the files wherever it can read them.
//
// What can fail: the managed overload and the ArrayView1D overload (into a caller buffer pre-filled with 0xAB, so
// a decoder that wrote elsewhere / short leaves 0xAB), RGBA8 and RGBA16 output, and the error paths, which must
// throw ImageDecodeException with the specific reason.

using ILGPU;
using ILGPU.Runtime;
using SpawnDev.Codecs.Images;
using SpawnDev.Codecs.Images.Bmp;
using SpawnDev.ILGPU;
using SpawnDev.UnitTesting;
using static SpawnDev.Codecs.Demo.Shared.UnitTests.TestHelpers;

namespace SpawnDev.Codecs.Demo.Shared.UnitTests;

public abstract partial class CodecsTestBase
{
    private const string BmpFixturePrefix = "SpawnDev.Codecs.Demo.Shared.TestData.Bmp.";

    private static string[] GifBmpFixtureNames(string prefix, string extension)
    {
        var names = typeof(CodecsTestBase).Assembly.GetManifestResourceNames()
            .Where(n => n.StartsWith(prefix, StringComparison.Ordinal) && n.EndsWith(extension, StringComparison.Ordinal))
            .Select(n => n.Substring(prefix.Length, n.Length - prefix.Length - extension.Length))
            .OrderBy(n => n, StringComparer.Ordinal)
            .ToArray();
        if (names.Length == 0) throw new InvalidOperationException($"No {extension} fixtures are embedded under {prefix}.");
        return names;
    }

    [TestMethod]
    public async Task BmpDecoderGpu_AllFixtures_Rgba8_MatchTruth_ManagedAndArrayView()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new BmpDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in GifBmpFixtureNames(BmpFixturePrefix, ".bmp"))
            {
                byte[] bmp = ReadEmbedded(BmpFixturePrefix + name + ".bmp");
                byte[] expected = ReadEmbedded(BmpFixturePrefix + name + ".rgba8");
                try
                {
                    // Managed overload.
                    var managed = await dec.DecodeAsync(bmp);
                    var diff = ComparePixels(expected, managed.Pixels, 4, managed.Info.Width);
                    if (diff != null) failures.Add($"{name} [managed]: {diff}");

                    // ArrayView1D overload into a poisoned caller buffer, longer than needed.
                    using var dFile = acc.Allocate1D<byte>(bmp.Length + 11);
                    DeviceTransfer.Upload(dFile.View, bmp);
                    using var dOut = acc.Allocate1D<byte>(expected.Length + 7);
                    var fill = new byte[dOut.Length];
                    System.Array.Fill(fill, (byte)0xAB);
                    DeviceTransfer.Upload(dOut.View, fill);
                    var info = await dec.DecodeAsync(dFile.View, bmp.Length, dOut.View, PixelFormat.Rgba8);
                    var viewPixels = await DeviceTransfer.DownloadAsync(dOut.View, expected.Length);
                    diff = ComparePixels(expected, viewPixels, 4, info.Width);
                    if (diff != null) failures.Add($"{name} [ArrayView1D]: {diff}");
                    var tail = await dOut.View.SubView(expected.Length, 7).CopyToHostAsync();
                    if (tail.Any(b => b != 0xAB)) failures.Add($"{name} [ArrayView1D]: wrote past the end of the pixel area");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(failures.Count == 0,
                $"{failures.Count} of {checkedCount + failures.Count} BMP fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task BmpDecoderGpu_AllFixtures_Rgba16_MatchTruth()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new BmpDecoderGpu(acc);
            var failures = new List<string>();
            int checkedCount = 0;
            foreach (var name in GifBmpFixtureNames(BmpFixturePrefix, ".bmp"))
            {
                byte[] bmp = ReadEmbedded(BmpFixturePrefix + name + ".bmp");
                byte[] truth8 = ReadEmbedded(BmpFixturePrefix + name + ".rgba8");
                // 8 -> 16 bit is v * 257, little endian: both bytes equal v.
                var expected = new byte[truth8.Length * 2];
                for (int i = 0; i < truth8.Length; i++) { expected[i * 2] = truth8[i]; expected[i * 2 + 1] = truth8[i]; }
                try
                {
                    var managed = await dec.DecodeAsync(bmp, PixelFormat.Rgba16);
                    var diff = ComparePixels(expected, managed.Pixels, 8, managed.Info.Width);
                    if (diff != null) failures.Add($"{name}: {diff}");
                    checkedCount++;
                }
                catch (Exception ex)
                {
                    failures.Add($"{name}: {ex.GetType().Name}: {ex.Message}");
                }
            }
            True(failures.Count == 0,
                $"{failures.Count} of {checkedCount + failures.Count} RGBA16 BMP fixtures failed:\n" + string.Join("\n", failures));
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    [TestMethod]
    public async Task BmpDecoderGpu_ReadInfo_ReportsHeaderFacts()
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new BmpDecoderGpu(acc);
            var pal4 = await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "pal4_21x9.bmp"));
            Equal(ImageFormat.Bmp, pal4.Format, "format");
            Equal(21, pal4.Width, "width");
            Equal(9, pal4.Height, "height");
            Equal(4, pal4.BitDepth, "palette bit depth");
            True(!pal4.HasAlpha, "palette image has no alpha");
            Equal(1, pal4.FrameCount, "frames");

            var topDown = await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "rgb24_13x11_topdown.bmp"));
            Equal(13, topDown.Width, "top-down width");
            Equal(11, topDown.Height, "top-down height is the absolute value");
            Equal(8, topDown.BitDepth, "24 bit reports 8 bits per channel");
            True(!topDown.HasAlpha, "24 bit has no alpha");

            True((await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "rgb32_alpha.bmp"))).HasAlpha, "32 bit BI_RGB can carry alpha");
            True((await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "bf16_4444_alpha.bmp"))).HasAlpha, "4444 has alpha");
            True(!(await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "bf16_565.bmp"))).HasAlpha, "565 has no alpha");
            True((await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "rle8_delta_gaps.bmp"))).HasAlpha, "RLE can leave transparent pixels");
            var core = await dec.ReadInfoAsync(ReadEmbedded(BmpFixturePrefix + "core_pal8.bmp"));
            Equal(7, core.Width, "core header width");
            Equal(6, core.Height, "core header height");
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    private async Task AssertBmpRejectedAsync(byte[] file, string expectedMessagePart, string what)
    {
        var (ctx, acc) = await AcquireAcceleratorOrSkipAsync();
        try
        {
            using var dec = new BmpDecoderGpu(acc);
            ImageDecodeException? caught = null;
            try { await dec.DecodeAsync(file); }
            catch (ImageDecodeException ex) { caught = ex; }
            NotNull(caught, $"{what}: expected ImageDecodeException");
            Contains(expectedMessagePart, caught!.Message, what);
        }
        finally { acc.Dispose(); ctx.Dispose(); }
    }

    private static byte[] BmpFixture(string name) => ReadEmbedded(BmpFixturePrefix + name + ".bmp");

    private static void PutLe32(byte[] file, int offset, uint value)
    {
        file[offset] = (byte)value; file[offset + 1] = (byte)(value >> 8);
        file[offset + 2] = (byte)(value >> 16); file[offset + 3] = (byte)(value >> 24);
    }

    [TestMethod]
    public async Task BmpDecoderGpu_BadSignature_IsRejected()
    {
        var bmp = BmpFixture("rgb24_13x11");
        bmp[1] = (byte)'X';
        await AssertBmpRejectedAsync(bmp, "bad signature", "bad signature");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_TruncatedHeader_IsRejected()
    {
        var bmp = BmpFixture("rgb24_13x11");
        await AssertBmpRejectedAsync(bmp.AsSpan(0, 30).ToArray(), "ends inside the headers", "file cut inside the DIB header");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_TruncatedPixelData_IsRejected()
    {
        var bmp = BmpFixture("rgb24_13x11");
        await AssertBmpRejectedAsync(bmp.AsSpan(0, bmp.Length - 5).ToArray(), "pixel data needs", "last row cut short");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_TruncatedPalette_IsRejected()
    {
        var bmp = BmpFixture("pal8_17x13");
        // Cut inside the 256-entry palette (14 + 40 + 100 bytes in).
        await AssertBmpRejectedAsync(bmp.AsSpan(0, 14 + 40 + 100).ToArray(), "palette", "file cut inside the palette");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_UnsupportedHeaderSize_IsRejected()
    {
        var bmp = BmpFixture("rgb24_13x11");
        PutLe32(bmp, 14, 64);   // OS/2 2.x header size
        await AssertBmpRejectedAsync(bmp, "unsupported DIB header size 64", "OS/2 2.x header");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_JpegAndPngCompression_AreRejected()
    {
        var jpeg = BmpFixture("rgb24_13x11");
        PutLe32(jpeg, 30, 4);
        await AssertBmpRejectedAsync(jpeg, "BI_JPEG", "BI_JPEG");
        var png = BmpFixture("rgb24_13x11");
        PutLe32(png, 30, 5);
        await AssertBmpRejectedAsync(png, "BI_PNG", "BI_PNG");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_BadDimensionsPlanesAndBitDepth_AreRejected()
    {
        var zeroWidth = BmpFixture("rgb24_13x11");
        PutLe32(zeroWidth, 18, 0);
        await AssertBmpRejectedAsync(zeroWidth, "invalid image size", "zero width");

        var planes = BmpFixture("rgb24_13x11");
        planes[26] = 2;
        await AssertBmpRejectedAsync(planes, "plane count", "two planes");

        var depth = BmpFixture("rgb24_13x11");
        depth[28] = 2;   // 2 bits per pixel
        await AssertBmpRejectedAsync(depth, "unsupported bit depth 2", "2 bpp");

        var huge = BmpFixture("rgb24_13x11");
        PutLe32(huge, 18, 100000);
        PutLe32(huge, 22, 100000);
        await AssertBmpRejectedAsync(huge, "too large", "100000 x 100000");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_NonContiguousMask_IsRejected()
    {
        var bmp = BmpFixture("bf16_565");   // BITMAPINFOHEADER + BITFIELDS: masks at 54, 58, 62
        PutLe32(bmp, 54, 0xF0F0);
        await AssertBmpRejectedAsync(bmp, "not contiguous", "red mask 0xF0F0");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_RleOutOfBounds_IsRejected()
    {
        var bmp = BmpFixture("rle8_basic");
        int off = bmp[10] | (bmp[11] << 8);   // pixel data offset
        bmp[off] = 200;                       // first run: 200 pixels into a 16 pixel wide image
        await AssertBmpRejectedAsync(bmp, "draws outside the image", "RLE run past the row");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_RleTruncated_IsRejected()
    {
        var bmp = BmpFixture("rle8_basic");
        int off = bmp[10] | (bmp[11] << 8);
        // Keep the first instruction (2 bytes) and one byte of the next.
        await AssertBmpRejectedAsync(bmp.AsSpan(0, off + 3).ToArray(), "RLE data is truncated", "RLE stream cut inside an instruction");
    }

    [TestMethod]
    public async Task BmpDecoderGpu_TopDownRle_IsRejected()
    {
        var bmp = BmpFixture("rle8_basic");
        PutLe32(bmp, 22, unchecked((uint)-6));
        await AssertBmpRejectedAsync(bmp, "cannot be top-down", "negative height with RLE");
    }
}
